async function collectPages(baseUrl, id, query) {
  const pages = [];
  let cursor = null;
  do {
    const suffix = cursor === null ? query : `${query}&cursor=${encodeURIComponent(cursor)}`;
    const page = await requestJson(baseUrl, `/scenarios/${id}/events?${suffix}`);
